2	//!
3	//! [`TerminalUI`] is the generic interactive UI used by every command
4	//! (init, status, list, run, …). For run-path workflow chrome and step
5	//! rendering, see [`crate::runner::display`].
6	
7	use console::Term;
8	use std::io::Write;
9	use std::sync::Arc;
10	
11	use crate::error::Result;
12	use crate::ui::surface::TerminalSurface;
13	
14	use super::{
15	    prompt_user, should_use_colors, BivvyTheme, NonInteractiveUI, OutputMode, OutputWriter,
16	    ProgressDisplay, ProgressSpinner, Prompt, PromptResult, Prompter, SpinnerFactory,
17	    SpinnerHandle, UiState, UserInterface,
18	};
19	
20	#[cfg(unix)]
21	use crate::shell::command::claim_foreground;
22	
23	/// Interactive terminal UI implementation.
24	///
25	/// During a workflow run an [`Arc<TerminalSurface>`] is attached via
26	/// [`TerminalUI::with_surface`]; output then flows through the surface
27	/// so it stays coordinated with the workflow's pinned bar and the
28	/// active step's transient region. Outside of a run the surface is
29	/// `None` and output is written directly to the terminal.
30	pub struct TerminalUI {
31	    term: Term,
32	    theme: BivvyTheme,
33	    mode: OutputMode,
34	    surface: Option<Arc<TerminalSurface>>,
35	}
36	
37	impl TerminalUI {
38	    /// Create a new terminal UI.
39	    pub fn new(mode: OutputMode) -> Self {
40	        let theme = if should_use_colors() {
41	            BivvyTheme::new()
42	        } else {
43	            BivvyTheme::plain()
44	        };
45	
46	        Self {
47	            term: Term::stdout(),
48	            theme,
49	            mode,
50	            surface: None,
51	        }
52	    }
53	
54	    /// Print a line through the surface (above bars) or directly to
55	    /// the terminal if no surface is attached.
56	    fn println(&mut self, line: &str) {
57	        if let Some(surface) = &self.surface {
58	            surface.println(line);
59	        } else {
60	            writeln!(self.term, "{}", line).ok();
61	        }
62	    }
63	}
64	
