402	fn resolve_feedback(
403	    store: &FeedbackStore,
404	    id: &str,
405	    note: Option<String>,
406	    ui: &mut dyn UserInterface,
407	) -> Result<i32> {
408	    let resolution = note.unwrap_or_else(|| "Resolved".to_string());
409	
410	    let found = store.update(id, |entry| {
411	        entry.resolve(&resolution);
412	    })?;
413	
414	    if found {
415	        ui.success(&format!("Resolved {}", id));
416	        Ok(0)
417	    } else {
418	        ui.error(&format!("Feedback {} not found", id));
419	        Ok(1)
420	    }
421	}
