1	//! Step decision logic for workflow execution.
2	//!
3	//! This module contains types and helpers for deciding what to do with a step
4	//! before execution: run it, skip it, block it, or prompt the user.
5	
6	use std::collections::HashSet;
7	
8	use crate::config::schema::StepOverride;
9	use crate::steps::ResolvedStep;
10	
11	/// What to do with a step before execution.
12	///
13	/// Produced by the pre-step evaluation phase. The orchestrator acts on this
14	/// decision — running, skipping, prompting, or blocking the step accordingly.
15	#[derive(Debug, Clone, PartialEq, Eq)]
16	pub enum StepDecision {
17	    /// Execute the step (user explicitly requested, e.g. via prompt response).
18	    Run,
19	    /// Auto-run the step without prompting. The decision engine determined the
20	    /// step is not satisfied and should execute.
21	    AutoRun,
22	    /// Auto-skip the step without prompting.
23	    Skip { reason: SkipReason },
24	    /// Ask the user whether to run/skip/re-run.
25	    Prompt { prompt_key: String },
26	    /// The step cannot proceed — a hard stop.
27	    Block { reason: BlockReason },
28	}
29	
30	/// Why a step was blocked and cannot proceed.
31	#[derive(Debug, Clone, PartialEq, Eq)]
32	pub enum BlockReason {
33	    /// A dependency of this step failed.
34	    DependencyFailed { dependency: String },
35	    /// A dependency of this step was skipped by the user and is not satisfied.
36	    DependencySkipped { dependency: String },
37	    /// A precondition check failed.
38	    PreconditionFailed { description: String },
39	    /// A dependency was skipped and its `satisfied_when` conditions failed.
40	    DependencyUnsatisfied { dependency: String },
41	}
42	
43	impl BlockReason {
44	    /// User-facing message for the block reason, naming the specific
45	    /// dependency or precondition that caused the block.
46	    pub fn message(&self) -> String {
47	        match self {
48	            BlockReason::DependencyFailed { dependency } => {
49	                format!("Blocked (dependency '{}' failed)", dependency)
50	            }
51	            BlockReason::DependencySkipped { dependency } => {
52	                format!("Skipped (dependency '{}' skipped)", dependency)
53	            }
54	            BlockReason::PreconditionFailed { description } => {
55	                format!("Blocked (precondition failed: {})", description)
56	            }
57	            BlockReason::DependencyUnsatisfied { dependency } => {
58	                format!("Blocked (dependency '{}' not satisfied)", dependency)
59	            }
60	        }
61	    }
62	}
63	
64	/// Why a step was skipped without execution.
65	#[derive(Debug, Clone, PartialEq, Eq)]
66	pub enum SkipReason {
67	    /// The step's completed check passed (work already done).
68	    CheckPassed,
69	    /// The step's `satisfied_when` conditions all passed (purpose already fulfilled).
70	    Satisfied,
71	    /// The decision engine auto-determined that the step is satisfied
72	    /// (via computed satisfaction: checks, rerun window, or explicit conditions).
73	    AutoSatisfied,
74	    /// The user declined to run the step.
75	    UserDeclined,
76	    /// The user declined a sensitive step.
77	    SensitiveDeclined,
78	    /// A requirement gap could not be resolved.
79	    RequirementNotMet,
80	}
81	
82	impl SkipReason {
83	    /// User-facing message for the skip reason.
84	    pub fn message(&self) -> &'static str {
85	        match self {
86	            SkipReason::CheckPassed => "Already complete",
87	            SkipReason::Satisfied => "Already satisfied",
88	            SkipReason::AutoSatisfied => "Already satisfied",
89	            SkipReason::UserDeclined => "Skipped",
90	            SkipReason::SensitiveDeclined => "Skipped (declined sensitive step)",
91	            SkipReason::RequirementNotMet => "Skipped (requirement not met)",
92	        }
93	    }
94	}
95	
96	/// Check if a step is blocked by a failed dependency.
97	pub fn blocked_by_failure(step: &ResolvedStep, failed_steps: &HashSet<String>) -> bool {
98	    step.depends_on.iter().any(|dep| failed_steps.contains(dep))
99	}
100	
101	/// Check if a step should be auto-skipped due to a user-skipped dependency.
102	///
103	/// A user-skipped dependency only blocks dependents if it is NOT satisfied.
104	/// If the skipped dependency's `satisfied_when` conditions passed, dependents
105	/// can proceed — the step's purpose is already fulfilled.
106	pub fn blocked_by_user_skip(
107	    step: &ResolvedStep,
108	    user_skipped: &HashSet<String>,
109	    satisfied_steps: &HashSet<String>,
110	) -> bool {
111	    step.depends_on
112	        .iter()
113	        .any(|dep| user_skipped.contains(dep) && !satisfied_steps.contains(dep))
114	}
115	
116	/// Resolve the effective `auto_run` value for a step, considering
117	/// step-level overrides from workflow environments.
118	pub fn effective_auto_run(
119	    step: &ResolvedStep,
120	    step_name: &str,
121	    step_overrides: &std::collections::HashMap<String, StepOverride>,
122	) -> bool {
123	    step_overrides
124	        .get(step_name)
125	        .and_then(|o| o.auto_run)
126	        .unwrap_or(step.behavior.auto_run)
127	}
128	
129	/// Resolve the effective `prompt_on_rerun` value for a step, considering
130	/// step-level overrides from workflow environments.
131	pub fn effective_prompt_on_rerun(
132	    step: &ResolvedStep,
133	    step_name: &str,
134	    step_overrides: &std::collections::HashMap<String, StepOverride>,
135	) -> bool {
136	    step_overrides
137	        .get(step_name)
138	        .and_then(|o| o.prompt_on_rerun)
139	        .unwrap_or(step.behavior.prompt_on_rerun)
140	}
141	
142	#[cfg(test)]
143	mod tests {
144	    use super::*;
145	    use crate::steps::{
146	        ResolvedBehavior, ResolvedEnvironmentVars, ResolvedExecution, ResolvedHooks,
147	        ResolvedOutput, ResolvedScoping, ResolvedStep,
148	    };
149	    use std::collections::HashMap;
150	
151	    fn make_step(name: &str, depends_on: Vec<String>) -> ResolvedStep {
152	        ResolvedStep {
153	            name: name.to_string(),
154	            title: name.to_string(),
155	            description: None,
156	            depends_on,
157	            requires: vec![],
158	            inputs: HashMap::new(),
159	            satisfied_when: vec![],
160	            execution: ResolvedExecution {
161	                command: format!("echo {}", name),
162	                ..Default::default()
163	            },
164	            env_vars: ResolvedEnvironmentVars::default(),
165	            behavior: ResolvedBehavior::default(),
166	            hooks: ResolvedHooks::default(),
167	            output: ResolvedOutput::default(),
168	            scoping: ResolvedScoping::default(),
169	        }
170	    }
171	
172	    #[test]
173	    fn blocked_by_failure_when_dep_failed() {
174	        let step = make_step("b", vec!["a".to_string()]);
175	        let mut failed = HashSet::new();
176	        failed.insert("a".to_string());
177	        assert!(blocked_by_failure(&step, &failed));
178	    }
179	
180	    #[test]
181	    fn not_blocked_when_dep_succeeded() {
182	        let step = make_step("b", vec!["a".to_string()]);
183	        let failed = HashSet::new();
184	        assert!(!blocked_by_failure(&step, &failed));
185	    }
186	
187	    #[test]
188	    fn blocked_by_user_skip_when_dep_skipped_and_unsatisfied() {
189	        let step = make_step("b", vec!["a".to_string()]);
190	        let mut skipped = HashSet::new();
