599	    /// Handle an auto-satisfied step (check passed, no prompt needed).
600	    fn handle_auto_satisfied(
601	        &self,
602	        eval_result: &EvaluationResult,
603	        step_header_text: &str,
604	        step_pad: &str,
605	        needs_force: bool,
606	        event_bus: &mut EventBus,
607	        step_display: &mut dyn StepDisplay,
608	    ) -> Result<StepAction> {
609	        event_bus.emit(&BivvyEvent::StepDecided {
610	            name: self.step_name.to_string(),
611	            decision: "skip".to_string(),
612	            reason: Some("auto_satisfied".to_string()),
613	            trace: Some(DecisionTrace {
614	                behavior_flags: make_behavior_flags(self.step, needs_force),
615	                ..Default::default()
616	            }),
617	        });
618	        event_bus.emit(&BivvyEvent::StepSkipped {
619	            name: self.step_name.to_string(),
620	            reason: eval_result.reason.clone(),
621	        });
622	        event_bus.emit(&BivvyEvent::StepOutcome {
623	            name: self.step_name.to_string(),
624	            outcome: StepOutcomeKind::Satisfied,
625	            detail: Some(eval_result.reason.clone()),
626	            duration_ms: None,
627	        });
628	        step_display.message(step_header_text);
629	        let skip_label = crate::ui::satisfaction_label(&eval_result.reason);
630	        step_display.message(&format!(
631	            "{}{}",
632	            step_pad,
633	            StatusKind::Success.format(self.theme, &skip_label)
634	        ));
635	        Ok(StepAction::Skipped(
636	            StepResult::check_passed(
637	                &self.step.name,
638	                CheckResult::passed(eval_result.reason.clone()),
639	            ),
640	            SkipCategory::Satisfied,
641	        ))
642	    }
