789	                options: vec!["Yes (y)".to_string(), "No  (n)".to_string()],
790	            });
791	            let answer = ui.prompt(&prompt)?;
792	            let answer_str = answer.as_string();
793	            event_bus.emit(&BivvyEvent::UserResponded {
794	                step: Some(self.step_name.to_string()),
795	                input: answer_str.clone(),
796	                method: crate::logging::InputMethod::ArrowSelect,
797	            });
798	            if answer_str != "yes" {
799	                // clear_lines removed — surface tracks regions
800	                event_bus.emit(&BivvyEvent::StepDecided {
801	                    name: self.step_name.to_string(),
802	                    decision: "skip".to_string(),
803	                    reason: Some("user_declined".to_string()),
