814	                    duration_ms: None,
815	                });
816	                step_display.message(&format!(
817	                    "{}{}",
818	                    step_pad,
819	                    self.theme.format_skipped("Skipped")
820	                ));
821	                return Ok(Some(StepAction::Skipped(
822	                    StepResult::skipped(&self.step.name, CheckResult::passed("User declined")),
823	                    SkipCategory::UserDeclined,
824	                )));
825	            }
826	            // clear_lines removed — surface tracks regions
827	        } else if prompt_key.starts_with("sensitive_") {
828	            let prompt_text = "Handles sensitive data. Continue?";
829	            let prompt = Prompt {
830	                key: prompt_key.to_string(),
