                Key::Char(chr) => {
                    chars.push(chr);
                    let mut bytes_char = [0; 4];
                    chr.encode_utf8(&mut bytes_char);
                    slf.write_str(chr.encode_utf8(&mut bytes_char))?;
                    slf.flush()?;
                }
                Key::Enter => {
                    slf.write_through(format!("\n{initial}").as_bytes())?;
                    break;
                }
                _ => (),
            }
        }
        Ok(chars.iter().skip(prefix_len).collect::<String>())

