1	//! Per-step display contract.
2	//!
3	//! A [`StepDisplay`] is created by [`super::WorkflowDisplay::begin_step`]
4	//! and lives for exactly one step. It owns:
5	//!
6	//! - The step header line written into scrollback.
7	//! - A transient region (above the workflow's pinned bar) that hosts a
8	//!   spinner with a bounded live-output tail.
9	//! - The error block, prompts, and final result line.
10	//!
11	//! ## Lifecycle
12	//!
13	//! 1. [`StepDisplay::show_step_header`] writes the step header line.
14	//! 2. [`StepDisplay::start_running`] mounts the transient region with
15	//!    the spinner and reserves `max_lines` for the live-output tail.
16	//! 3. [`StepDisplay::update_live_output`] appends to the ring buffer
17	//!    backing the spinner's message.
18	//! 4. One of the `finish_*` methods consumes `Box<Self>`. The transient
19	//!    region is dropped (cleared) and a final result line is written
20	//!    into scrollback.
21	//!
22	//! `Drop` on `Box<dyn StepDisplay>` is a panic-safety net only — the
23	//! `finish_*` methods are the canonical close path.
24	
25	use std::collections::VecDeque;
26	use std::sync::Arc;
27	use std::time::Duration;
28	
29	use indicatif::{ProgressBar, ProgressStyle};
30	
31	use crate::error::Result;
32	use crate::shell::OutputLine;
33	use crate::steps::StepStatus;
34	use crate::ui::progress::format_duration;
35	use crate::ui::surface::{TerminalSurface, TransientRegion};
36	use crate::ui::theme::BivvyTheme;
37	use crate::ui::{prompt_user, OutputMode, OutputWriter, Prompt, PromptResult, Prompter};
38	
39	#[cfg(unix)]
40	use crate::shell::command::claim_foreground;
41	
42	/// Per-step display contract.
43	///
44	/// Extends [`OutputWriter`] and [`Prompter`] so the step display is
45	/// drop-in compatible with code paths that expect those traits
46	/// (recovery menu, gap installer). Implementors must ensure that
47	/// calling any `finish_*` method cleanly closes the transient region
48	/// before returning.
49	pub trait StepDisplay: OutputWriter + Prompter {
50	    /// Write the step header line into scrollback.
51	    fn show_step_header(&mut self, step_name: &str, title: Option<&str>);
52	
53	    /// Mount the transient region with a spinner.
54	    ///
55	    /// The `command` is normalized to a single line (newlines collapsed
56	    /// to spaces, truncated). The transient region reserves room for
57	    /// the live-output tail.
58	    fn start_running(&mut self, command: &str);
59	
60	    /// Append a line of live command output to the spinner's tail.
61	    ///
62	    /// No-op if the transient region has not been mounted.
63	    fn update_live_output(&mut self, line: OutputLine);
64	
65	    /// Finalize the step. Clears the transient region and prints the
66	    /// final result line into scrollback. The label and icon are
67	    /// derived from `status` (via [`StepStatus::label`] and
68	    /// [`StepStatus::display_char`]) so the displayed text is always
69	    /// in lockstep with the actual step outcome.
70	    ///
71	    /// Optional `duration` is shown in parentheses after the label;
72	    /// optional `detail` is appended dimmed.
73	    fn finish(&mut self, status: StepStatus, duration: Option<Duration>, detail: Option<&str>);
74	
75	    /// Finalize the step without writing a final line — used when the
76	    /// caller will write its own final state afterwards (auto-satisfied
77	    /// step, blocked dependency, etc.).
78	    fn finish_and_clear(&mut self);
79	
80	    /// The output mode currently in effect.
81	    fn output_mode(&self) -> OutputMode;
82	
83	    /// Width (in columns) at which content should be indented to align
84	    /// under the step name. `step_indent() == step_number().chars().count() + 1`.
85	    fn step_indent(&self) -> usize;
86	
87	    /// The step number string, e.g. `[1/3]`.
88	    fn step_number(&self) -> &str;
89	
90	    /// Whether the underlying surface supports interactive prompts.
91	    fn is_interactive(&self) -> bool;
92	
93	    /// Build an [`OutputCallback`] that feeds command output into the
94	    /// transient region's live-output tail. Returns `None` if the
95	    /// display has no live-output concept (silent / non-interactive
96	    /// non-verbose).
97	    fn live_output_callback(&mut self) -> Option<crate::shell::OutputCallback> {
98	        None
99	    }
100	}
101	
102	// ────────────────────────── Interactive impl ──────────────────────────
103	
104	const RING_BUFFER_VERBOSE: usize = 3;
105	const RING_BUFFER_NORMAL: usize = 2;
106	/// Cap on a single line of live output before truncation.
107	const MAX_OUTPUT_LINE_LEN: usize = 72;
108	
109	/// How many tail lines to ring-buffer for the given output mode.
110	fn live_tail_capacity(mode: OutputMode) -> usize {
111	    match mode {
112	        OutputMode::Verbose => RING_BUFFER_VERBOSE,
113	        OutputMode::Normal => RING_BUFFER_NORMAL,
114	        _ => 0,
115	    }
116	}
117	
118	/// Interactive per-step display backed by a [`TerminalSurface`].
119	pub struct TerminalStepDisplay {
120	    surface: Arc<TerminalSurface>,
121	    theme: BivvyTheme,
122	    mode: OutputMode,
123	    step_number: String,
124	    step_indent: usize,
125	    region: Option<TransientRegion>,
126	    /// Ring-buffer of recent live-output lines for the spinner tail.
127	    tail: VecDeque<String>,
128	    /// Spinner base message — preserved so live-output updates don't
129	    /// drop the "Running ..." prefix.
130	    base_message: String,
131	    /// Maximum tail capacity (depends on output mode).
132	    tail_capacity: usize,
133	}
134	
135	impl TerminalStepDisplay {
136	    /// Construct a new terminal step display.
137	    pub fn new(
138	        surface: Arc<TerminalSurface>,
139	        mode: OutputMode,
140	        index: usize,
141	        total: usize,
142	    ) -> Self {
143	        let theme = if crate::ui::should_use_colors() {
144	            BivvyTheme::new()
145	        } else {
146	            BivvyTheme::plain()
147	        };
148	        let step_number = format!("[{}/{}]", index + 1, total);
149	        let step_indent = step_number.chars().count() + 1;
150	        Self {
151	            surface,
152	            theme,
153	            mode,
154	            step_number,
155	            step_indent,
156	            region: None,
157	            tail: VecDeque::new(),
158	            base_message: String::new(),
159	            tail_capacity: live_tail_capacity(mode),
160	        }
161	    }
162	
163	    /// Collapse a multi-line command into a single line.
164	    fn normalize_command(command: &str) -> String {
165	        let collapsed = command
166	            .lines()
167	            .map(|l| l.trim())
168	            .filter(|l| !l.is_empty())
169	            .collect::<Vec<_>>()
170	            .join("; ");
171	        if collapsed.chars().count() > 96 {
172	            let mut out: String = collapsed.chars().take(93).collect();
173	            out.push_str("...");
174	            out
175	        } else {
176	            collapsed
177	        }
178	    }
179	
180	    /// Truncate a single output line for display in the tail.
181	    fn truncate_line(line: &str) -> String {
182	        let trimmed = line.trim_end();
183	        if trimmed.chars().count() > MAX_OUTPUT_LINE_LEN {
184	            let mut out: String = trimmed
185	                .chars()
186	                .take(MAX_OUTPUT_LINE_LEN.saturating_sub(3))
187	                .collect();
188	            out.push_str("...");
189	            out
190	        } else {
191	            trimmed.to_string()
192	        }
193	    }
194	
195	    /// Render the spinner message: base + tail buffer (already truncated).
196	    fn render_message(&self) -> String {
197	        let prefix = " ".repeat(self.step_indent.saturating_add(2));
198	        let mut msg = self.base_message.clone();
199	        for line in &self.tail {
200	            msg.push('\n');
201	            msg.push_str(&prefix);
202	            msg.push_str(&self.theme.dim.apply_to(format!("» {}", line)).to_string());
203	        }
204	        msg
205	    }
206	}
207	
208	impl OutputWriter for TerminalStepDisplay {
209	    fn message(&mut self, msg: &str) {
210	        if self.mode.shows_status() {
211	            self.surface.println(msg);
212	        }
213	    }
214	
215	    fn success(&mut self, msg: &str) {
216	        if self.mode.shows_status() {
217	            self.surface
218	                .println(&self.theme.format_success(msg).to_string());
219	        }
220	    }
221	
222	    fn warning(&mut self, msg: &str) {
223	        if self.mode.shows_status() {
224	            self.surface
225	                .println(&self.theme.format_warning(msg).to_string());
226	        }
227	    }
228	
229	    fn error(&mut self, msg: &str) {
230	        self.surface
231	            .println(&self.theme.format_error(msg).to_string());
232	    }
233	
234	    fn show_hint(&mut self, hint: &str) {
235	        if self.mode.shows_status() {
236	            self.surface
237	                .println(&self.theme.hint.apply_to(hint).to_string());
238	            self.surface.println("");
239	        }
240	    }
241	
242	    fn show_error_block(&mut self, command: &str, output: &str, hint: Option<&str>, indent: usize) {
243	        let b = &self.theme.border;
244	        let pad = " ".repeat(indent);
245	        let mut lines = vec![
246	            format!(
247	                "{}{} {}",
248	                pad,
249	                b.apply_to("┌─"),
250	                b.apply_to("Command ──────────────────────────")
251	            ),
252	            format!(
253	                "{}{} {}",
254	                pad,
255	                b.apply_to("│"),
256	                self.theme.command.apply_to(command)
257	            ),
258	        ];
259	
260	        if !output.is_empty() {
261	            lines.push(format!(
262	                "{}{} {}",
263	                pad,
264	                b.apply_to("├─"),
265	                b.apply_to("Output ───────────────────────────")
266	            ));
267	            for line in output.lines() {
268	                lines.push(format!("{}{} {}", pad, b.apply_to("│"), line));
269	            }
270	        }
271	
272	        lines.push(format!(
273	            "{}{}",
274	            pad,
275	            b.apply_to("└────────────────────────────────────")
276	        ));
277	
278	        if let Some(h) = hint {
279	            lines.push(String::new());
280	            lines.push(format!(
281	                "{}{} {}",
282	                pad,
283	                self.theme.hint.apply_to("Hint:"),
284	                self.theme.hint.apply_to(h)
285	            ));
286	        }
287	
288	        for line in &lines {
289	            self.surface.println(line);
290	        }
291	    }
292	}
