454	// ─────────────────────── Non-interactive impl ────────────────────────
455	
456	/// Non-interactive (CI / headless) per-step display.
457	pub struct NonInteractiveStepDisplay {
458	    mode: OutputMode,
459	    step_number: String,
460	    step_indent: usize,
461	}
462	
463	impl NonInteractiveStepDisplay {
464	    /// Construct a new non-interactive step display.
465	    pub fn new(mode: OutputMode, index: usize, total: usize) -> Self {
466	        let step_number = format!("[{}/{}]", index + 1, total);
467	        let step_indent = step_number.chars().count() + 1;
468	        Self {
469	            mode,
470	            step_number,
471	            step_indent,
472	        }
473	    }
474	}
475	
476	impl OutputWriter for NonInteractiveStepDisplay {
477	    fn message(&mut self, msg: &str) {
478	        if self.mode.shows_status() {
479	            println!("{}", msg);
480	        }
481	    }
482	
483	    fn success(&mut self, msg: &str) {
484	        if self.mode.shows_status() {
485	            println!("✓ {}", msg);
486	        }
487	    }
488	
489	    fn warning(&mut self, msg: &str) {
490	        if self.mode.shows_status() {
491	            eprintln!("⚠ {}", msg);
492	        }
493	    }
494	
495	    fn error(&mut self, msg: &str) {
496	        eprintln!("✗ {}", msg);
497	    }
498	
499	    fn show_hint(&mut self, hint: &str) {
500	        if self.mode.shows_status() {
501	            println!("  💡 {}", hint);
502	        }
503	    }
504	
505	    fn show_error_block(&mut self, command: &str, output: &str, hint: Option<&str>, indent: usize) {
506	        let pad = " ".repeat(indent);
507	        eprintln!();
508	        eprintln!("{}┌─ Command ──────────────────────────", pad);
509	        eprintln!("{}│ {}", pad, command);
510	        if !output.is_empty() {
511	            eprintln!("{}├─ Output ───────────────────────────", pad);
512	            for line in output.lines() {
513	                eprintln!("{}│ {}", pad, line);
514	            }
515	        }
516	        eprintln!("{}└────────────────────────────────────", pad);
517	        if let Some(h) = hint {
518	            eprintln!();
519	            eprintln!("{}Hint: {}", pad, h);
520	        }
521	    }
522	}
523	
524	impl Prompter for NonInteractiveStepDisplay {
525	    fn prompt(&mut self, prompt: &Prompt) -> Result<PromptResult> {
526	        // Non-interactive: reuse env override or default logic.
527	        let is_multiselect = matches!(
528	            prompt.prompt_type,
529	            crate::ui::PromptType::MultiSelect { .. }
530	        );
531	        if let Some(result) = crate::ui::prompts::env_override(prompt) {
532	            return Ok(result);
533	        }
534	        if let Some(default) = &prompt.default {
535	            if is_multiselect {
536	                let values: Vec<String> =
537	                    default.split(',').map(|s| s.trim().to_string()).collect();
538	                return Ok(PromptResult::Strings(values));
539	            }
540	            return Ok(PromptResult::String(default.clone()));
541	        }
542	        Err(crate::error::BivvyError::ConfigValidationError {
543	            message: format!(
544	                "Cannot prompt for '{}' in non-interactive mode (no default value)",
545	                prompt.key
546	            ),
547	        })
548	    }
549	}
550	
551	impl StepDisplay for NonInteractiveStepDisplay {
552	    fn show_step_header(&mut self, step_name: &str, title: Option<&str>) {
553	        if !self.mode.shows_status() {
554	            return;
555	        }
556	        match title {
557	            Some(t) if t != step_name => {
558	                println!("{} {} — {}", self.step_number, step_name, t);
559	            }
560	            _ => println!("{} {}", self.step_number, step_name),
561	        }
562	    }
563	
564	    fn start_running(&mut self, command: &str) {
565	        if !self.mode.shows_spinners() {
566	            return;
567	        }
568	        let collapsed = TerminalStepDisplay::normalize_command(command);
569	        let prefix = " ".repeat(self.step_indent);
570	        println!("{}Running `{}`...", prefix, collapsed);
571	    }
572	
573	    fn update_live_output(&mut self, line: OutputLine) {
574	        if !matches!(self.mode, OutputMode::Verbose) {
575	            return;
576	        }
577	        match line {
578	            OutputLine::Stdout(s) => print!("{}", s),
579	            OutputLine::Stderr(s) => eprint!("{}", s),
580	        }
581	    }
582	
583	    fn finish(&mut self, status: StepStatus, duration: Option<Duration>, detail: Option<&str>) {
584	        if !self.mode.shows_status() && !matches!(status, StepStatus::Failed) {
585	            return;
586	        }
587	        let label = status.label();
588	        let body = match duration {
589	            Some(d) => format!("{} ({})", label, format_duration(d)),
590	            None => label.to_string(),
591	        };
592	        let detail_str = detail.map(|d| format!(" — {}", d)).unwrap_or_default();
593	        let pad = " ".repeat(self.step_indent);
594	        let line = format!("{}{} {}{}", pad, status.display_char(), body, detail_str);
595	        if matches!(status, StepStatus::Failed) {
596	            eprintln!("{}", line);
597	        } else {
598	            println!("{}", line);
599	        }
600	    }
601	
602	    fn finish_and_clear(&mut self) {}
603	
604	    fn output_mode(&self) -> OutputMode {
605	        self.mode
606	    }
607	
608	    fn step_indent(&self) -> usize {
609	        self.step_indent
610	    }
611	
612	    fn step_number(&self) -> &str {
613	        &self.step_number
614	    }
615	
616	    fn is_interactive(&self) -> bool {
617	        false
618	    }
619	
620	    fn live_output_callback(&mut self) -> Option<crate::shell::OutputCallback> {
621	        if matches!(self.mode, OutputMode::Verbose) {
622	            Some(Box::new(crate::ui::VerboseStreamSink::new(
623	                self.step_indent,
624	            )))
625	        } else {
626	            None
627	        }
628	    }
629	}
