        let resolutions = vec![
            make_resolution("update pg_dump", "brew install postgresql@16", 0.7),
            make_resolution(
                "fix PATH",
                "export PATH=/opt/homebrew/opt/postgresql@16/bin:$PATH",
                0.65,
            ),
