33	/// Mock UI implementation for testing.
34	///
35	/// Captures all UI interactions and allows pre-configured prompt responses.
36	/// Supports both single responses (via `set_prompt_response`) and queued
37	/// responses (via `queue_prompt_responses`) for keys called multiple times.
38	#[derive(Debug, Default)]
39	pub struct MockUI {
40	    mode: OutputMode,
41	    interactive: bool,
42	    messages: Vec<String>,
43	    successes: Vec<String>,
44	    warnings: Vec<String>,
45	    errors: Vec<String>,
46	    headers: Vec<String>,
47	    hints: Vec<String>,
48	    progress: Vec<(usize, usize)>,
49	    spinners: Vec<String>,
50	    error_blocks: Vec<(String, String, Option<String>, usize)>,
51	    prompt_responses: HashMap<String, String>,
52	    prompt_queues: HashMap<String, VecDeque<String>>,
53	    prompts_shown: Vec<String>,
54	    /// Fallback response for any prompt key not in `prompt_responses` or `prompt_queues`.
55	    default_prompt_response: Option<String>,
56	}
