58	impl MockUI {
59	    /// Create a new MockUI with Normal output mode.
60	    pub fn new() -> Self {
61	        Self {
62	            mode: OutputMode::Normal,
63	            ..Default::default()
64	        }
65	    }
66	
67	    /// Create a new MockUI with a specific output mode.
68	    pub fn with_mode(mode: OutputMode) -> Self {
69	        Self {
70	            mode,
71	            ..Default::default()
72	        }
73	    }
74	
75	    /// Set a response for a prompt key.
76	    ///
77	    /// When `prompt()` is called with this key, it returns the configured response.
78	    pub fn set_prompt_response(&mut self, key: &str, response: &str) {
79	        self.prompt_responses
80	            .insert(key.to_string(), response.to_string());
81	    }
