223	        self.error_blocks.push((
224	            command.to_string(),
225	            output.to_string(),
226	            hint.map(|h| h.to_string()),
227	            indent,
228	        ));
229	        self.errors.push(command.to_string());
230	        if !output.is_empty() {
231	            self.messages.push(output.to_string());
232	        }
233	        if let Some(h) = hint {
234	            self.hints.push(h.to_string());
235	        }
236	    }
