        assert!(result_yn.is_err(), "yes/no should error on non-TTY");
        assert!(result_multi.is_err(), "multi should error on non-TTY");
    }

    // -----------------------------------------------------------------------
    // Ctrl+D / EOF graceful handling tests
    // -----------------------------------------------------------------------

    #[test]
    fn map_dialoguer_err_converts_unexpected_eof_to_user_cancelled() {
        let eof_err =
            dialoguer::Error::IO(std::io::Error::new(std::io::ErrorKind::UnexpectedEof, "EOF"));
        let bivvy_err = map_dialoguer_err(eof_err);
        assert!(
            matches!(bivvy_err, BivvyError::UserCancelled),
            "UnexpectedEof should become UserCancelled, got: {:?}",
            bivvy_err
        );
    }

    #[test]
    fn map_dialoguer_err_preserves_other_io_errors() {
        let io_err = dialoguer::Error::IO(std::io::Error::new(
            std::io::ErrorKind::PermissionDenied,
            "denied",
        ));
        let bivvy_err = map_dialoguer_err(io_err);
        assert!(
            matches!(bivvy_err, BivvyError::Io(_)),
            "Non-EOF IO errors should remain as Io, got: {:?}",
            bivvy_err
        );
    }

    #[test]
    fn ctrl_d_byte_is_eof_char() {
        assert_eq!(EOF_CHAR, '\x04', "Ctrl+D should be 0x04");
    }
}

