    } else {
        BivvyError::Io(e)
    }
}

/// Convert dialoguer errors to BivvyError.
///
/// `UnexpectedEof` (triggered by Ctrl+D) becomes `UserCancelled` so
/// callers can exit gracefully instead of propagating a raw IO error.
fn map_dialoguer_err(e: dialoguer::Error) -> BivvyError {
    map_io_eof(e.into())
}

