            return; // Skip under --nocapture with real TTY
        }

        let options = vec![
            PromptOption {
                label: "Yes (y)".to_string(),
                value: "yes".to_string(),
            },
            PromptOption {
                label: "No (n)".to_string(),
                value: "no".to_string(),
            },
        ];
        let prompt = make_prompt(
            "rerun_step",
            PromptType::Select {
                options: options.clone(),
            },
            Some("yes"),
        );

        // Call the REAL prompt code, not MockUI.
        // No SIGTTOU, no panic, no crash — just a clean IO error.
        let result = prompt_select(&prompt, &options, &term);
        assert!(result.is_err());
    }

    #[test]
    fn yes_no_and_multi_option_selects_error_consistently() {
        // Verify that yes/no prompts and multi-option selects produce
        // the same kind of error on non-TTY. If yes/no had a different
        // code path that crashed instead of erroring, this test would
        // catch it.
        let term = Term::stdout();
        if term.is_term() {
            return; // Skip under --nocapture with real TTY
        }

        // 2-option yes/no (takes the custom prompt_yes_no path)
        let yn_options = vec![
            PromptOption {
                label: "Yes (y)".to_string(),
                value: "yes".to_string(),
            },
            PromptOption {
                label: "No (n)".to_string(),
                value: "no".to_string(),
            },
        ];
        let yn_prompt = make_prompt(
            "yn",
            PromptType::Select {
                options: yn_options.clone(),
            },
            Some("yes"),
        );

        // 3-option select (goes through dialoguer's Select)
        let multi_options = vec![
            PromptOption {
                label: "A".to_string(),
                value: "a".to_string(),
            },
            PromptOption {
                label: "B".to_string(),
                value: "b".to_string(),
            },
            PromptOption {
                label: "C".to_string(),
                value: "c".to_string(),
            },
        ];
        let multi_prompt = make_prompt(
            "multi",
            PromptType::Select {
                options: multi_options.clone(),
            },
            Some("a"),
        );

        // Both must error on non-TTY — neither should panic or crash.
        let result_yn = prompt_select(&yn_prompt, &yn_options, &term);
        let result_multi = prompt_select(&multi_prompt, &multi_options, &term);

        assert!(result_yn.is_err(), "yes/no should error on non-TTY");
        assert!(result_multi.is_err(), "multi should error on non-TTY");
    }

    // -----------------------------------------------------------------------
    // Ctrl+D / EOF graceful handling tests
    // -----------------------------------------------------------------------

    #[test]
    fn map_dialoguer_err_converts_unexpected_eof_to_user_cancelled() {
        let eof_err =
            dialoguer::Error::IO(std::io::Error::new(std::io::ErrorKind::UnexpectedEof, "EOF"));
        let bivvy_err = map_dialoguer_err(eof_err);
        assert!(
            matches!(bivvy_err, BivvyError::UserCancelled),
            "UnexpectedEof should become UserCancelled, got: {:?}",
            bivvy_err
        );
    }

    #[test]
    fn map_dialoguer_err_preserves_other_io_errors() {
        let io_err = dialoguer::Error::IO(std::io::Error::new(
            std::io::ErrorKind::PermissionDenied,
            "denied",
        ));
        let bivvy_err = map_dialoguer_err(io_err);
        assert!(
            matches!(bivvy_err, BivvyError::Io(_)),
            "Non-EOF IO errors should remain as Io, got: {:?}",
            bivvy_err
        );
    }

}

